export function resolveReviewedNote(value,fragment=''){
  const [source,embedded]=String(value||'').split('#');
  const target=reviewedNavigation[source];
  if(!target)return null;
  const hash=(embedded??fragment).replace(/^#/,'');
  let decoded=hash;try{decoded=decodeURIComponent(hash);}catch{}
  const mapped=reviewedFragments[source]?.[decoded];
  if(hash&&mapped&&typeof mapped==='object')return {...target,...mapped};
  return {...target,anchor:hash?(mapped||decoded):target.anchor};
}
